private async assertCiFree(ci: string, exceptPersonId?: string) {
    (1) const person = await this.prisma.person.findUnique({
        where: { ci },
        include: { adopterProfile: { select: { id: true } } },
    });
    (2) if (person &&
        (3) person.id !== exceptPersonId) {
        (4) throw new ConflictException({
            message: `Ya existe un adoptante registrado con la CI ${ci}`,
            errors: { existingAdopterId: person.adopterProfile?.id ?? null },
        });
    }
}

async create(dto: CreateAdoptionDto, user: AuthUser) {
    (1) const adopter = await this.prisma.adopterProfile.findUnique({
        where: { id: dto.adopterId },
    });
    (2) if (!adopter) throw new NotFoundException('Adoptante no encontrado');

    try {
        (3) return await this.prisma.$transaction(async (tx) => {
            const animal = await this.status.getForUpdate(tx, dto.animalId);
            (4) if (animal.status === 'EN_PROCESO_ADOPCION') {
                (5) throw new ConflictException('El animal ya tiene una solicitud de adopción activa');
            }
            (6) if (animal.status !== 'DISPONIBLE_ADOPCION') {
                (7) throw new ConflictException(
                    `El animal no está disponible para adopción (estado: ${STATUS_LABELS[animal.status]})`,
                );
            }
            (8) const request = await tx.adoptionRequest.create({
                data: {
                    adopterProfileId: dto.adopterId,
                    animalId: dto.animalId,
                    responsibleUserId: user.id,
                    status: 'PENDIENTE',
                    evaluationNotes: appendNote(null, dto.notes, user, 'Pendiente'),
                },
            });
            await this.status.changeStatus(tx, animal, 'EN_PROCESO_ADOPCION');
            return request;
        });
    } catch (err) {
        (9) if (err instanceof Prisma.PrismaClientKnownRequestError &&
            (10) err.code === 'P2002') {
            (11) throw new ConflictException('El animal ya tiene una solicitud de adopción activa');
        }
        (12) throw err;
    }
}

private async score(
    adopter: AdopterInput,
    animal: AnimalInput,
    settings: AlgorithmSettings,
): Promise<ScoredResult> {
    (1) const rules = computeCompatibility(adopter, animal, settings);
    const base = { ...rules, ruleScore: rules.score };

    (2) if (!rules.hardFilters.passed) {
        (3) return { ...base, method: 'REGLAS', ml: null };
    }

    (4) const active = await this.ml.activeForest();
    (5) if (!active) {
        (6) return { ...base, method: 'REGLAS', ml: null };
    }

    (7) const features = toFeatures(adopter, animal);
    const probability = active.forest.predictProba(features);
    const score = Math.round(probability * 100 * 100) / 100;

    return {
        ...base,
        score,
        level: levelFor(score, settings),
        method: 'MODELO',
        ml: {
            modelVersion: active.version,
            algorithm: 'random-forest',
            probability: Math.round(probability * 10000) / 10000,
            agreement: Math.round(active.forest.agreement(features) * 10000) / 10000,
            factors: active.forest.explain(features).map((f) => ({
                feature: f.feature,
                label: FEATURE_LABELS[f.feature as FeatureName] ?? f.feature,
                value: f.value,
                contribution: f.contribution,
                direction: f.direction,
            })),
        },
    };
}

export function levelFor(
    score: number,
    s: Pick<AlgorithmSettings, 'thresholdHigh' | 'thresholdMedium'>,
): Level {
    (1) if (score >= s.thresholdHigh) return 'ALTA';
    (2) if (score >= s.thresholdMedium) return 'MEDIA';
    (3) return 'BAJA';
}

async closePeriod(periodId: string, dto: ClosePeriodDto, user: AuthUser) {
    (1) const period = await this.activePeriodOrThrow(periodId);
    (6) if (new Date(dto.endDate) < period.startDate) {
        throw new BadRequestException('La fecha de fin no puede ser anterior al inicio del periodo');
    }
    (7) if (period._count.controls === 0 &&
        (8) !dto.confirmWithoutControls) {
        (9) throw new ConflictException({
            message: 'El periodo no tiene controles registrados. Confirma para cerrarlo igualmente.',
            errors: [
                {
                    field: 'confirmWithoutControls',
                    messages: ['Se requiere confirmación'],
                },
            ],
        });
    }
    (10) const { _count } = period;
    return this.prisma.$transaction(async (tx) => {
        const closed = await tx.quarantinePeriod.update({
            where: { id: periodId },
            data: {
                status: 'FINALIZADO',
                endDate: new Date(dto.endDate),
                finalObservations: dto.finalObservations,
                closedById: user.id,
            },
        });
        await this.status.syncClinicalStatus(tx, period.animalId);
        return { ...closed, controlsCount: _count.controls };
    });
}

private async activePeriodOrThrow(id: string) {
    (2) const p = await this.prisma.quarantinePeriod.findUnique({
        where: { id },
        include: { _count: { select: { controls: true } } },
    });
    (3) if (!p) throw new NotFoundException('Periodo no encontrado');
    (4) if (p.status !== 'ACTIVO') throw new ConflictException('El periodo ya está finalizado');
    (5) return p;
}

async enableAdoption(id: string): Promise<Animal> {
    (1) return this.prisma.$transaction(async (tx) => {
        const animal = await this.status.getForUpdate(tx, id);
        (2) if (animal.status === 'DISPONIBLE_ADOPCION') {
            throw new ConflictException('El animal ya está disponible para adopción');
        }
        (3) const blockers = await this.status.adoptionBlockers(tx, animal);
        (4) if (blockers.length) {
            throw new ConflictException({
                message: `No se puede habilitar para adopción: ${blockers.join('; ')}`,
                errors: blockers,
            });
        }
        (5) return this.status.changeStatus(tx, animal, 'DISPONIBLE_ADOPCION');
    });
}

async decide(id: string, dto: DecisionDto, user: AuthUser) {
    (1) const decisionDate = new Date(dto.decisionDate);
    let deliveryDate: Date | null = null;
    (2) if (dto.result === 'APROBADA') {
        (3) if (!dto.deliveryDate) {
            throw new BadRequestException('La fecha de entrega es obligatoria al aprobar');
        }
        (4) deliveryDate = new Date(dto.deliveryDate);
        (5) if (deliveryDate.getTime() < decisionDate.getTime() - 86_400_000) {
            throw new BadRequestException('La fecha de entrega no puede ser anterior a la decisión');
        }
    }

    return this.prisma.$transaction(async (tx) => {
        (6) const req = await this.lockRequest(tx, id);
        (9) if (req.status !== 'EN_EVALUACION') {
            throw new ConflictException(
                `Solo se puede registrar el resultado de una solicitud en evaluación (estado actual: ${REQUEST_STATUS_LABELS[req.status]})`,
            );
        }
        (10) assertRequestTransition(req.status, dto.result);
        const updated = await tx.adoptionRequest.update({
            where: { id },
            data: {
                status: dto.result,
                decisionDate,
                deliveryDate,
                evaluationNotes: appendNote(
                    req.evaluationNotes,
                    dto.notes,
                    user,
                    REQUEST_STATUS_LABELS[dto.result],
                ),
            },
        });
        (11) if (dto.result === 'APROBADA') {
            (12) const animal = await this.status.getForUpdate(tx, req.animalId);
            await this.status.changeStatus(tx, animal, animalStatusAfter('APROBADA'));
        } else {
            (13) await this.releaseAnimal(tx, req.animalId);
        }
        (14) return updated;
    });
}

private async lockRequest(tx: Tx, id: string): Promise<AdoptionRequest> {
    (7) await tx.$executeRaw`SELECT id FROM adoption_requests WHERE id = ${id}::uuid FOR UPDATE`;
    const req = await tx.adoptionRequest.findUnique({ where: { id } });
    (8) if (!req) throw new NotFoundException('Solicitud no encontrada');
    return req;
}

